import * as React from "react";
import { createRoot } from "react-dom/client";
import { OrientationSelector } from "./orientation-selector";
import "./taskpane.css";

Office.onReady(() => {
  const rootElement = document.getElementById("root");
  if (!rootElement) {
    return;
  }

  createRoot(rootElement).render(
    <React.StrictMode>
      <OrientationSelector />
    </React.StrictMode>
  );
});
