import * as React from "react";
import {
  getOrientation,
  setOrientation,
  type Orientation,
} from "../settings/orientation-settings";

async function recalculateWorkbook(): Promise<void> {
  await Excel.run(async (context) => {
    context.workbook.application.calculate(Excel.CalculationType.full);
    await context.sync();
  });
}

export function OrientationSelector(): React.JSX.Element {
  const [orientation, setOrientationState] = React.useState<Orientation>(() => getOrientation());

  const handleChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const mode = event.target.value as Orientation;
    setOrientationState(mode);
    setOrientation(mode);
    await recalculateWorkbook();
  };

  return (
    <section className="orientation-panel" aria-labelledby="orientation-title">
      <h1 id="orientation-title" className="orientation-title">
        Spill orientation
      </h1>
      <p className="orientation-description">
        Choose how TESTVELIXO.FACTORIALROW spills its results.
      </p>
      <fieldset className="orientation-options">
        <legend className="orientation-legend">Orientation</legend>
        <label className="orientation-option">
          <input
            type="radio"
            name="orientation"
            value="row"
            checked={orientation === "row"}
            onChange={handleChange}
          />
          <span>Row</span>
        </label>
        <label className="orientation-option">
          <input
            type="radio"
            name="orientation"
            value="column"
            checked={orientation === "column"}
            onChange={handleChange}
          />
          <span>Column</span>
        </label>
      </fieldset>
    </section>
  );
}
