export type Orientation = "row" | "column";

export const orientationStorageKey = "factorial-add-in-orientation";

export function isOrientation(value: unknown): value is Orientation {
  return value === "row" || value === "column";
}

export function getOrientation(): Orientation {
  try {
    const stored = localStorage.getItem(orientationStorageKey);
    if (stored === null) {
      return "row";
    }

    return isOrientation(stored) ? stored : "row";
  } catch {
    return "row";
  }
}

export function setOrientation(orientation: Orientation): void {
  localStorage.setItem(orientationStorageKey, orientation);
}
